1	import { lazy, Suspense, useEffect } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	import { supabase } from "@/integrations/supabase/client";
14	
15	// Eager imports — core pages users navigate between constantly (no Suspense flash)
16	import Index from "./pages/Index";
17	import Auth from "./pages/Auth";
18	import Settings from "./pages/Settings";
19	import Profile from "./pages/Profile";
20	import Billing from "./pages/Billing";
21	import Team from "./pages/Team";
22	import Tasks from "./pages/Tasks";
23	import Activity from "./pages/Activity";
24	
25	// Sidebar-accessible pages — eager to avoid flash on click
26	import Changelog from "./pages/Changelog";
27	import RequestFeature from "./pages/RequestFeature";
28	import CareerSettings from "./pages/CareerSettings";
29	import Integrations from "./pages/Integrations";
30	import ApiDocs from "./pages/ApiDocs";
31	
32	// Lazy imports — infrequent or large pages
33	const Admin = lazy(() => import("./pages/Admin"));
34	const NotFound = lazy(() => import("./pages/NotFound"));
35	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
36	const BookDemo = lazy(() => import("./pages/BookDemo"));
37	const Apply = lazy(() => import("./pages/Apply"));
38	const CareerPage = lazy(() => import("./pages/CareerPage"));
39	const CareerJobDetail = lazy(() => import("./pages/CareerJobDetail"));
40	const LandingPage = lazy(() => import("@/components/LandingPage"));
41	const SharedPortal = lazy(() => import("./pages/SharedPortal"));
42	const BookInterview = lazy(() => import("./pages/BookInterview"));
43	
44	const queryClient = new QueryClient({
45	  defaultOptions: {
46	    queries: {
47	      staleTime: 5 * 60 * 1000,
48	      gcTime: 10 * 60 * 1000,
49	      refetchOnWindowFocus: false,
50	      refetchOnMount: false,
51	      retry: 1,
52	    },
53	  },
54	});
55	
56	/** Full-width skeleton that matches the sidebar+content layout to prevent layout shift */
57	const PageLoader = () => (
58	  <div className="flex h-svh w-full overflow-hidden">
59	    {/* Sidebar skeleton — matches sidebar width */}
60	    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
61	      <div className="px-4 py-4">
62	        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
63	      </div>
64	      <div className="border-t border-border" />
65	      <div className="p-3 space-y-2">
66	        {[1, 2, 3, 4].map((i) => (
67	          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
68	        ))}
69	      </div>
70	    </div>
71	    {/* Content area skeleton */}
72	    <div className="flex-1 flex flex-col min-w-0">
73	      {/* Header skeleton */}
74	      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
75	        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
76	        <div className="flex items-center gap-3">
77	          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
78	          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
79	        </div>
80	      </div>
81	      {/* Body skeleton */}
82	      <div className="flex-1 overflow-y-auto p-6">
83	        <div className="max-w-5xl mx-auto space-y-4">
84	          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
85	          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
86	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
87	            {[1, 2, 3, 4].map((i) => (
88	              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
89	            ))}
90	          </div>
91	        </div>
92	      </div>
93	    </div>
94	  </div>
95	);
96	
97	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
98	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
99	  const { isAdmin, loading } = useAuth();
100	
101	  // Don't block rendering while loading — only gate when we know maintenance is on
102	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
103	  return <>{children}</>;
104	};
105	
106	const RootRoute = () => {
107	  const { user, loading } = useAuth();
108	  if (loading) return <PageLoader />;
109	  return user ? <Index /> : <LandingPage />;
110	};
111	
112	/** Silently prefetches sidebar-linked pages so they open instantly on first click */
113	const DataPrefetcher = () => {
114	  const { user } = useAuth();
115	  const qc = useQueryClient();
116	
117	  useEffect(() => {
118	    // Prefetch public data that doesn't require auth
119	    qc.prefetchQuery({
120	      queryKey: ["changelog_public"],
121	      queryFn: async () => {
122	        const { data } = await (supabase as any)
123	          .from("changelog")
124	          .select("id, version, title, description, category, published_at")
125	          .eq("status", "published")
126	          .order("published_at", { ascending: false });
127	        return data ?? [];
128	      },
129	      staleTime: 5 * 60 * 1000,
130	    });
131	    qc.prefetchQuery({
132	      queryKey: ["feature_requests"],
133	      queryFn: async () => {
134	        const { data } = await (supabase as any)
135	          .from("feature_requests")
136	          .select("*")
137	          .order("created_at", { ascending: false });
138	        return data ?? [];
139	      },
140	      staleTime: 5 * 60 * 1000,
141	    });
142	  }, []);
143	
144	  useEffect(() => {
145	    if (!user) return;
146	    qc.prefetchQuery({
147	      queryKey: ["my_feature_votes"],
148	      queryFn: async () => {
149	        const { data } = await (supabase as any)
150	          .from("feature_request_votes")
151	          .select("feature_request_id")
152	          .eq("user_id", user.id);
153	        return (data ?? []).map((v: any) => v.feature_request_id);
154	      },
155	      staleTime: 5 * 60 * 1000,
156	    });
157	  }, [user?.id]);
158	
159	  return null;
160	};
161	
162	const App = () => (
163	  <QueryClientProvider client={queryClient}>
164	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
165	      <AuthProvider>
166	        <DataPrefetcher />
167	        <TooltipProvider>
168	          <Sonner />
169	          <BrowserRouter>
170	            <SeoHead />
171	            <Suspense fallback={<PageLoader />}>
172	              <Routes>
173	                {/* Public pages — outside MaintenanceGate so candidates/guests can always access */}
174	                <Route path="/apply/:jobId" element={<Apply />} />
175	                <Route path="/careers/:slug" element={<CareerPage />} />
176	                <Route path="/careers/:slug/jobs/:jobId" element={<CareerJobDetail />} />
177	                <Route path="/shared/:token" element={<SharedPortal />} />
178	                <Route path="/book/:token" element={<BookInterview />} />
179	                <Route path="*" element={
180	                  <MaintenanceGate>
181	                    <Routes>
182	                      <Route path="/auth" element={<Auth />} />
183	                      <Route path="/" element={<RootRoute />} />
184	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
185	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
186	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
187	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
188	                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
189	                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
190	                      <Route path="/activity" element={<ProtectedRoute><Activity /></ProtectedRoute>} />
191	                      <Route path="/career-settings" element={<ProtectedRoute><CareerSettings /></ProtectedRoute>} />
192	                      <Route path="/integrations" element={<ProtectedRoute><Integrations /></ProtectedRoute>} />
193	                      <Route path="/api-docs" element={<ProtectedRoute><ApiDocs /></ProtectedRoute>} />
194	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
195	                      <Route path="/book-demo" element={<BookDemo />} />
196	                      <Route path="/request-feature" element={<RequestFeature />} />
197	                      <Route path="/changelog" element={<Changelog />} />
198	                      <Route path="/payment/callback" element={<PaymentCallback />} />
199	                      <Route path="*" element={<NotFound />} />
200	                    </Routes>
201	                  </MaintenanceGate>
202	                } />
203	              </Routes>
204	            </Suspense>
205	            <ChatWidget />
206	          </BrowserRouter>
207	        </TooltipProvider>
208	      </AuthProvider>
209	    </ThemeProvider>
210	  </QueryClientProvider>
211	);
212	
213	export default App;
214	
