1	import React, { useState } from "react";
2	import { Button } from "@/components/ui/button";
3	import { Badge } from "@/components/ui/badge";
4	import { Checkbox } from "@/components/ui/checkbox";
5	import { TableCell, TableRow } from "@/components/ui/table";
6	import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
7	import { Phone, Mail, MapPin, FileText, Archive, Linkedin, UserCheck } from "lucide-react";
8	import { extractLinkedInUrl } from "@/lib/linkedin";
9	import { toast } from "sonner";
10	import type { Result } from "@/pages/Index";
11	import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
12	import type { HiringStage } from "@/hooks/useStageTracker";
13	import type { CandidateTag } from "@/hooks/useCandidateTags";
14	
15	interface CandidateRowProps {
16	  result: Result;
17	  index: number;
18	  isSelected: boolean;
19	  isActive: boolean;
20	  jobId?: string | null;
21	  jobTitle?: string | null;
22	  onSelect: (id: string) => void;
23	  onToggleSelect: (resumeId: string) => void;
24	  onDownload: (filePath: string, filename: string) => void;
25	  onDismiss: (resumeId: string) => void;
26	  formatCandidateName: (filename: string) => string;
27	  currentStage?: HiringStage | null;
28	  isDuplicate?: boolean;
29	  tags?: CandidateTag[];
30	  assigneeEmail?: string | null;
31	}
32	
33	const getScoreColor = (score: number) => {
34	  if (score >= 70) return "bg-score-skills";
35	  if (score >= 40) return "bg-warning";
36	  return "bg-destructive";
37	};
38	
39	const getScoreTextColor = (score: number) => {
40	  if (score >= 70) return "text-score-skills";
41	  if (score >= 40) return "text-warning";
42	  return "text-destructive";
43	};
44	
45	const STAGE_BADGE_CLASSES: Record<string, string> = {
46	  applied: "border-border bg-muted/50 text-muted-foreground",
47	  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
48	  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
49	  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
50	  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
51	  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
52	};
53	
54	const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
55	  if (score >= 70) return { label: "Strong", variant: "success" };
56	  if (score >= 40) return { label: "Good", variant: "warning" };
57	  return { label: "Weak", variant: "destructive" };
58	};
59	
60	const CandidateRow = ({
61	  result: r,
62	  index,
63	  isSelected,
64	  isActive,
65	  jobId,
66	  jobTitle,
67	  onSelect,
68	  onToggleSelect,
69	  onDownload,
70	  onDismiss,
71	  formatCandidateName,
72	  currentStage,
73	  isDuplicate,
74	  tags = [],
75	  assigneeEmail,
76	}: CandidateRowProps) => {
77	  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
78	  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
79	  const linkedinUrl = extractLinkedInUrl(r);
80	
81	  return (
82	    <>
83	      <TableRow
84	        className={`transition-colors animate-in fade-in slide-in-from-bottom-1 duration-200 ${r.pending ? "opacity-50 cursor-default" : "cursor-pointer"} ${isActive ? "bg-primary/5 hover:bg-primary/5" : "hover:bg-muted/50"}`}
85	        style={{ animationDelay: `${Math.min(index * 40, 400)}ms`, animationFillMode: "backwards" }}
86	        onClick={() => !r.pending && onSelect(r.id)}
87	      >
88	        <TableCell onClick={(e) => e.stopPropagation()}>
89	          <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
90	        </TableCell>
91	        <TableCell className="text-center">
92	          {r.pending
93	            ? <span className="text-sm text-muted-foreground">—</span>
94	            : <span className="text-sm font-medium tabular-nums text-muted-foreground">{index + 1}</span>}
95	        </TableCell>
96	        <TableCell className="font-medium">
97	          <div className="flex flex-col gap-0.5">
98	            <div className="flex items-center gap-1.5 flex-wrap">
99	              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
100	              {isDuplicate && (
101	                <Badge variant="outline" className="text-[11px] px-1.5 py-0 border-orange-300 text-orange-600 bg-orange-50">
102	                  Duplicate
103	                </Badge>
104	              )}
105	              {!r.pending && currentStage && currentStage !== "applied" && (
106	                <Badge
107	                  variant="outline"
108	                  className={`text-[11px] px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
109	                >
110	                  {currentStage}
111	                </Badge>
112	              )}
113	            </div>
114	            {r.candidate_location && (
115	              <span className="flex items-center gap-1 text-xs text-muted-foreground">
116	                <MapPin className="h-3 w-3" /> {r.candidate_location}
117	              </span>
118	            )}
119	            {/* Tag chips */}
120	            {tags.length > 0 && (
121	              <div className="flex flex-wrap gap-1 mt-0.5">
122	                {tags.slice(0, 3).map((t) => (
123	                  <span
124	                    key={t.id}
125	                    className="inline-flex items-center px-1.5 py-0 rounded-full text-[10px] font-medium text-white leading-4"
126	                    style={{ backgroundColor: t.color }}
127	                  >
128	                    {t.tag}
129	                  </span>
130	                ))}
131	                {tags.length > 3 && (
132	                  <span className="text-[10px] text-muted-foreground">+{tags.length - 3}</span>
133	                )}
134	              </div>
135	            )}
136	            {/* Assignee badge */}
137	            {assigneeEmail && (
138	              <span className="text-[10px] text-muted-foreground flex items-center gap-0.5 mt-0.5">
139	                <UserCheck className="h-2.5 w-2.5" />
140	                {assigneeEmail}
141	              </span>
142	            )}
143	          </div>
144	        </TableCell>
145	        <TableCell>
146	          {r.pending ? (
147	            <Badge variant="outline" className="text-[11px]">Pending</Badge>
148	          ) : (
149	            <div className="flex items-center gap-2">
150	              <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
151	                <div
152	                  className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
153	                  style={{ width: `${Math.min(r.overall_score, 100)}%` }}
154	                />
155	              </div>
156	              <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
157	                {r.overall_score?.toFixed(0)}%
158	              </span>
159	            </div>
160	          )}
161	        </TableCell>
162	        <TableCell>
163	          <div className="flex flex-wrap items-center gap-1">
164	            {!r.pending && strength && (
165	              <Badge variant={strength.variant} className="text-[11px]">{strength.label}</Badge>
166	            )}
167	            {!r.pending && r.scoring_version === "heuristic" && (
168	              <span className="inline-flex items-center text-[11px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium">Quick</span>
169	            )}
170	          </div>
171	        </TableCell>
172	        <TableCell>
173	          <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
174	            {!isActive && (
175	            <TooltipProvider delayDuration={300}>
176	              {r.candidate_phone && (
177	                <Tooltip>
178	                  <TooltipTrigger asChild>
179	                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" aria-label="Copy phone number"
180	                      onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
181	                      <Phone className="h-3.5 w-3.5" />
182	                    </Button>
183	                  </TooltipTrigger>
184	                  <TooltipContent>{r.candidate_phone}</TooltipContent>
185	                </Tooltip>
186	              )}
187	              {r.candidate_email && (
188	                <Tooltip>
189	                  <TooltipTrigger asChild>
190	                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" aria-label="Send email"
191	                      onClick={() => setEmailDialogOpen(true)}>
192	                      <Mail className="h-3.5 w-3.5" />
193	                    </Button>
194	                  </TooltipTrigger>
195	                  <TooltipContent>Email</TooltipContent>
196	                </Tooltip>
197	              )}
198	              {linkedinUrl && (
199	                <Tooltip>
200	                  <TooltipTrigger asChild>
201	                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-[#0A66C2]"
202	                      onClick={(e) => { e.stopPropagation(); window.open(linkedinUrl, "_blank", "noopener,noreferrer"); }}>
203	                      <Linkedin className="h-3.5 w-3.5" />
204	                    </Button>
205	                  </TooltipTrigger>
206	                  <TooltipContent>LinkedIn Profile</TooltipContent>
207	                </Tooltip>
208	              )}
209	              {r.file_path && (
210	                <Tooltip>
211	                  <TooltipTrigger asChild>
212	                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" aria-label="Download resume"
213	                      onClick={() => onDownload(r.file_path!, r.filename)}>
214	                      <FileText className="h-3.5 w-3.5" />
215	                    </Button>
216	                  </TooltipTrigger>
217	                  <TooltipContent>Download</TooltipContent>
218	                </Tooltip>
219	              )}
220	              <Tooltip>
221	                <TooltipTrigger asChild>
222	                  <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-amber-500" aria-label="Archive candidate"
223	                    onClick={() => onDismiss(r.resume_id)}>
224	                    <Archive className="h-3.5 w-3.5" />
225	                  </Button>
226	                </TooltipTrigger>
227	                <TooltipContent>Archive</TooltipContent>
228	              </Tooltip>
229	            </TooltipProvider>
230	            )}
231	          </div>
232	        </TableCell>
233	      </TableRow>
234	
235	      {r.candidate_email && (
236	        <EmailOutreachDialog
237	          open={emailDialogOpen}
238	          onOpenChange={setEmailDialogOpen}
239	          candidateName={r.candidate_name || r.filename}
240	          candidateEmail={r.candidate_email}
241	          jobTitle={jobTitle || "Open Position"}
242	          matchScore={Math.round(r.overall_score ?? 0)}
243	          resumeId={r.resume_id}
244	          jobId={jobId || ""}
245	        />
246	      )}
247	    </>
248	  );
249	};
250	
251	export default React.memo(CandidateRow);
252	
