59	
60	type TeamRole = "owner" | "admin" | "member";
61	
62	const ROLE_LABELS: Record<TeamRole, string> = {
63	  owner: "Owner",
64	  admin: "Admin",
65	  member: "Member",
66	};
67	
68	const ROLE_VARIANTS: Record<TeamRole, "default" | "secondary" | "outline"> = {
69	  owner: "default",
70	  admin: "secondary",
71	  member: "outline",
