73	
74	function RoleBadge({ role }: { role: TeamRole }) {
75	  const Icon = role === "owner" ? Crown : role === "admin" ? Shield : Users;
76	  return (
77	    <Badge variant={ROLE_VARIANTS[role]} className="gap-1 text-xs font-medium">
78	      <Icon className="h-3 w-3" />
79	      {ROLE_LABELS[role]}
80	    </Badge>
81	  );
82	}
83	
84	function MembersSkeleton() {
