-- ─── Authenticity analysis on results ───────────────────────────────────────
ALTER TABLE results ADD COLUMN IF NOT EXISTS authenticity_json jsonb;

-- ─── Stage automations ────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS stage_automations (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id     uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  stage_name  text NOT NULL,
  action_type text NOT NULL CHECK (action_type IN ('send_email', 'add_tag', 'assign_member', 'webhook')),
  action_config jsonb NOT NULL DEFAULT '{}',
  is_active   boolean NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE stage_automations ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Team members can read their automations"
  ON stage_automations FOR SELECT
  USING (
    team_id IN (
      SELECT team_id FROM team_members WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "Team admins/owners can manage automations"
  ON stage_automations FOR ALL
  USING (
    team_id IN (
      SELECT team_id FROM team_members
      WHERE user_id = auth.uid() AND role IN ('owner', 'admin')
    )
  );

-- ─── Talent pool ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS talent_pool (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id         uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  resume_id       uuid NOT NULL REFERENCES resumes(id) ON DELETE CASCADE,
  original_job_id uuid REFERENCES jobs(id) ON DELETE SET NULL,
  added_by        uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  notes           text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (team_id, resume_id)
);

ALTER TABLE talent_pool ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Team members can read talent pool"
  ON talent_pool FOR SELECT
  USING (
    team_id IN (
      SELECT team_id FROM team_members WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "Team members can insert into talent pool"
  ON talent_pool FOR INSERT
  WITH CHECK (
    team_id IN (
      SELECT team_id FROM team_members WHERE user_id = auth.uid()
    )
    AND added_by = auth.uid()
  );

CREATE POLICY "Team admins/owners can delete from talent pool"
  ON talent_pool FOR DELETE
  USING (
    team_id IN (
      SELECT team_id FROM team_members
      WHERE user_id = auth.uid() AND role IN ('owner', 'admin')
    )
    OR added_by = auth.uid()
  );

CREATE INDEX IF NOT EXISTS talent_pool_team_id_idx ON talent_pool (team_id);
CREATE INDEX IF NOT EXISTS talent_pool_resume_id_idx ON talent_pool (resume_id);

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface AuthenticityResult {
  authenticity_score: number; // 0–100, higher = more authentic
  risk_level: "low" | "medium" | "high";
  flags: string[];
  summary: string;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    // Auth
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const token = authHeader.replace("Bearer ", "");
    const { data: { user }, error: authError } = await supabase.auth.getUser(token);
    if (authError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { resume_id } = await req.json() as { resume_id: string };
    if (!resume_id) {
      return new Response(JSON.stringify({ error: "resume_id is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Fetch resume data + result
    const { data: resume, error: resumeErr } = await supabase
      .from("resumes")
      .select("id, filename, parsed_text, job_id, parsed_json")
      .eq("id", resume_id)
      .single();

    if (resumeErr || !resume) {
      return new Response(JSON.stringify({ error: "Resume not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Verify the user owns the job
    const { data: job, error: jobErr } = await supabase
      .from("jobs")
      .select("id, user_id, job_description")
      .eq("id", resume.job_id)
      .single();

    if (jobErr || !job || job.user_id !== user.id) {
      return new Response(JSON.stringify({ error: "Forbidden" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const openaiKey = Deno.env.get("OPENAI_API_KEY");
    if (!openaiKey) throw new Error("OPENAI_API_KEY not configured");

    const parsed = typeof resume.parsed_json === "string"
      ? JSON.parse(resume.parsed_json)
      : resume.parsed_json ?? {};

    const resumeText = resume.parsed_text ?? JSON.stringify(parsed);
    const truncatedResume = resumeText.slice(0, 8000);

    const systemPrompt = `You are an expert resume fraud analyst. Analyze the provided resume for authenticity signals.

Return a JSON object ONLY with this structure:
{
  "authenticity_score": <integer 0-100, higher = more authentic>,
  "risk_level": <"low"|"medium"|"high">,
  "flags": [<array of specific concern strings, empty if none>],
  "summary": <1-2 sentence plain English summary>
}

Fraud signals to check:
- Date inconsistencies or impossible timelines (jobs overlapping completely, future dates)
- Skill inflation (claiming expert-level skills that conflict with experience duration)
- Generic filler content (overly templated, no specific projects/companies/metrics)
- Employment gap hiding (suspiciously round durations like "2 years" everywhere)
- Education credential mismatch (prestigious degree with poor English or basic roles)
- Exaggerated titles vs responsibilities described
- Copied buzzword soup without substance
- Implausible career progression speed

Score guide:
- 90-100: Highly authentic, no concerns
- 70-89: Mostly authentic, minor inconsistencies
- 50-69: Some concerns worth investigating
- 30-49: Notable red flags, verify carefully
- 0-29: High fraud risk

Return ONLY valid JSON, no markdown.`;

    const userPrompt = `Resume to analyze:\n\n${truncatedResume}`;

    const response = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${openaiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "gpt-4o",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: userPrompt },
        ],
        temperature: 0.2,
        max_tokens: 600,
        response_format: { type: "json_object" },
      }),
    });

    if (!response.ok) {
      const err = await response.text();
      throw new Error(`OpenAI error: ${err}`);
    }

    const completion = await response.json();
    const content = completion.choices?.[0]?.message?.content ?? "{}";
    const result: AuthenticityResult = JSON.parse(content);

    // Clamp score
    result.authenticity_score = Math.max(0, Math.min(100, Math.round(result.authenticity_score)));

    // Persist to results table
    await supabase
      .from("results")
      .update({ authenticity_json: result })
      .eq("resume_id", resume_id);

    return new Response(JSON.stringify(result), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error("check-authenticity error:", message);
    return new Response(JSON.stringify({ error: message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface ParsedFilters {
  min_score?: number;
  max_score?: number;
  skills?: string[];
  location?: string;
  stages?: string[];
  min_experience_years?: number;
  education_level?: string;
  semantic_query?: string;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const token = authHeader.replace("Bearer ", "");
    const { data: { user }, error: authError } = await supabase.auth.getUser(token);
    if (authError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { query, job_id } = await req.json() as { query: string; job_id?: string };
    if (!query?.trim()) {
      return new Response(JSON.stringify({ error: "query is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const openaiKey = Deno.env.get("OPENAI_API_KEY");
    if (!openaiKey) throw new Error("OPENAI_API_KEY not configured");

    // Step 1: Parse NL query into structured filters via GPT-4o
    const parseResponse = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${openaiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "gpt-4o",
        messages: [
          {
            role: "system",
            content: `You are a resume search query parser. Parse natural language queries about candidates into structured JSON filters.

Return ONLY valid JSON with this structure:
{
  "min_score": <number 0-100 or null>,
  "max_score": <number 0-100 or null>,
  "skills": [<array of skill strings or empty>],
  "location": <string or null>,
  "stages": [<array from: "applied","screened","interview","offer","hired","rejected" or empty>],
  "min_experience_years": <number or null>,
  "education_level": <"high_school"|"bachelor"|"master"|"phd" or null>,
  "semantic_query": <cleaned search terms for text search, or null>
}

Examples:
"Show me candidates with React over 80%" → {"min_score":80,"skills":["React"],"semantic_query":"React"}
"Senior engineers in New York" → {"location":"New York","min_experience_years":5,"semantic_query":"senior engineer"}
"Python developers in interview stage" → {"skills":["Python"],"stages":["interview"],"semantic_query":"Python developer"}`,
          },
          { role: "user", content: query },
        ],
        temperature: 0,
        max_tokens: 400,
        response_format: { type: "json_object" },
      }),
    });

    if (!parseResponse.ok) throw new Error("Failed to parse query");

    const parseCompletion = await parseResponse.json();
    const filters: ParsedFilters = JSON.parse(
      parseCompletion.choices?.[0]?.message?.content ?? "{}"
    );

    // Step 2: Build DB query using parsed filters
    let dbQuery = supabase
      .from("resumes")
      .select(`
        id,
        filename,
        candidate_name,
        candidate_location,
        candidate_email,
        job_id,
        status,
        parsed_json,
        results!inner (
          id,
          overall_score,
          skill_score,
          experience_score,
          education_score,
          missing_skills,
          strengths_json,
          gaps_json,
          authenticity_json
        ),
        jobs!inner (
          id,
          title,
          user_id
        )
      `)
      .eq("jobs.user_id", user.id)
      .eq("status", "done");

    if (job_id) {
      dbQuery = dbQuery.eq("job_id", job_id);
    }

    if (filters.min_score != null) {
      dbQuery = dbQuery.gte("results.overall_score", filters.min_score);
    }
    if (filters.max_score != null) {
      dbQuery = dbQuery.lte("results.overall_score", filters.max_score);
    }
    if (filters.location) {
      dbQuery = dbQuery.ilike("candidate_location", `%${filters.location}%`);
    }

    const { data: candidates, error: queryErr } = await dbQuery
      .order("results.overall_score", { ascending: false })
      .limit(50);

    if (queryErr) throw queryErr;

    // Step 3: Client-side filter for skills (if any)
    let filtered = candidates ?? [];

    if (filters.skills && filters.skills.length > 0) {
      const skillsLower = filters.skills.map((s) => s.toLowerCase());
      filtered = filtered.filter((c: any) => {
        const parsed = typeof c.parsed_json === "string"
          ? JSON.parse(c.parsed_json)
          : c.parsed_json ?? {};
        const candidateSkills: string[] = (parsed.skills ?? []).map((s: string) => s.toLowerCase());
        return skillsLower.some((skill) =>
          candidateSkills.some((cs) => cs.includes(skill))
        );
      });
    }

    if (filters.semantic_query) {
      const q = filters.semantic_query.toLowerCase();
      filtered = filtered.filter((c: any) => {
        const name = (c.candidate_name ?? c.filename ?? "").toLowerCase();
        const location = (c.candidate_location ?? "").toLowerCase();
        const parsed = typeof c.parsed_json === "string"
          ? JSON.parse(c.parsed_json)
          : c.parsed_json ?? {};
        const skills = (parsed.skills ?? []).join(" ").toLowerCase();
        const summary = (parsed.summary ?? "").toLowerCase();
        return (
          name.includes(q) ||
          location.includes(q) ||
          skills.includes(q) ||
          summary.includes(q)
        );
      });
    }

    const results = filtered.map((c: any) => ({
      resume_id: c.id,
      filename: c.filename,
      candidate_name: c.candidate_name,
      candidate_location: c.candidate_location,
      candidate_email: c.candidate_email,
      job_id: c.job_id,
      job_title: c.jobs?.title ?? null,
      overall_score: c.results?.[0]?.overall_score ?? 0,
      skill_score: c.results?.[0]?.skill_score ?? 0,
      experience_score: c.results?.[0]?.experience_score ?? 0,
      education_score: c.results?.[0]?.education_score ?? 0,
      authenticity_json: c.results?.[0]?.authenticity_json ?? null,
    }));

    return new Response(
      JSON.stringify({ results, filters, total: results.length }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error("ai-search error:", message);
    return new Response(JSON.stringify({ error: message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

