interface AuthenticityData {
  authenticity_score: number;
  risk_level: "low" | "medium" | "high";
  flags: string[];
  summary: string;
}

interface AuthenticityReportProps {
  resumeId: string;
  initialData?: AuthenticityData | null;
  onUpdate?: (data: AuthenticityData) => void;
}

const getRiskConfig = (riskLevel: "low" | "medium" | "high") => {
  switch (riskLevel) {
    case "low":
      return {
        icon: ShieldCheck,
        label: "Low Risk — Likely Authentic",
        scoreClass: "text-emerald-600 dark:text-emerald-400",
        barClass: "bg-emerald-500",
        bgClass: "bg-emerald-50 border-emerald-200 dark:bg-emerald-900/10 dark:border-emerald-800",
      };
    case "medium":
      return {
        icon: Shield,
        label: "Medium Risk — Review Recommended",
        scoreClass: "text-amber-600 dark:text-amber-400",
        barClass: "bg-amber-500",
        bgClass: "bg-amber-50 border-amber-200 dark:bg-amber-900/10 dark:border-amber-800",
      };
    case "high":
      return {
        icon: ShieldAlert,
        label: "High Risk — Verify Carefully",
        scoreClass: "text-red-600 dark:text-red-400",
        barClass: "bg-red-500",
        bgClass: "bg-red-50 border-red-200 dark:bg-red-900/10 dark:border-red-800",
      };
  }
};

const AuthenticityReport = ({ resumeId, initialData, onUpdate }: AuthenticityReportProps) => {
  const [data, setData] = useState<AuthenticityData | null>(initialData ?? null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const runCheck = async () => {
    setLoading(true);
    setError(null);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.access_token) throw new Error("Not authenticated");

      const res = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/check-authenticity`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${session.access_token}`,
            "apikey": import.meta.env.VITE_SUPABASE_ANON_KEY,
          },
          body: JSON.stringify({ resume_id: resumeId }),
        }
      );

      const json = await res.json();
      if (!res.ok) throw new Error(json.error ?? "Check failed");

      setData(json as AuthenticityData);
      onUpdate?.(json as AuthenticityData);
      toast.success("Authenticity check complete");
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Check failed";
      setError(msg);
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  if (!data && !loading && !error) {
    return (
      <div className="rounded-lg border border-dashed border-border p-4 flex flex-col items-center justify-center gap-2 text-center">
        <Shield className="h-8 w-8 text-muted-foreground/40" />
        <p className="text-sm font-medium text-muted-foreground">Authenticity not checked yet</p>
        <p className="text-xs text-muted-foreground/70">Run an AI-powered fraud analysis on this resume</p>
        <Button size="sm" variant="outline" className="mt-1 gap-1.5" onClick={runCheck}>
          <Shield className="h-3.5 w-3.5" />
          Run Authenticity Check
        </Button>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="rounded-lg border border-border p-4 flex items-center gap-3">
        <Loader2 className="h-4 w-4 animate-spin text-primary shrink-0" />
        <p className="text-sm text-muted-foreground">Analyzing resume for authenticity signals…</p>
      </div>
    );
  }

  if (error && !data) {
    return (
      <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-4 flex items-start gap-3">
        <AlertCircle className="h-4 w-4 text-destructive shrink-0 mt-0.5" />
        <div className="flex-1">
          <p className="text-sm text-destructive">{error}</p>
          <Button size="sm" variant="ghost" className="mt-1 h-7 text-xs gap-1" onClick={runCheck}>
            <RefreshCw className="h-3 w-3" /> Retry
          </Button>
        </div>
      </div>
    );
  }

  if (!data) return null;

  const config = getRiskConfig(data.risk_level);
  const Icon = config.icon;

  return (
    <div className={cn("rounded-lg border p-4 space-y-3", config.bgClass)}>
      {/* Header */}
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2">
          <Icon className={cn("h-4 w-4 shrink-0", config.scoreClass)} />
          <span className="text-sm font-semibold">{config.label}</span>
        </div>
        <Button
          size="sm"
          variant="ghost"
          className="h-6 w-6 p-0 shrink-0"
          onClick={runCheck}
          disabled={loading}
          aria-label="Re-run authenticity check"
        >
          <RefreshCw className="h-3 w-3" />
        </Button>
      </div>

      {/* Score bar */}
      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <span className="text-xs text-muted-foreground">Authenticity Score</span>
          <span className={cn("text-sm font-bold tabular-nums", config.scoreClass)}>
            {data.authenticity_score}%
          </span>
        </div>
        <div className="h-1.5 rounded-full bg-background/50 overflow-hidden">
          <div
            className={cn("h-full rounded-full transition-all duration-500", config.barClass)}
            style={{ width: `${data.authenticity_score}%` }}
          />
        </div>
      </div>

      {/* Summary */}
      <p className="text-xs text-muted-foreground leading-relaxed">{data.summary}</p>

      {/* Flags */}
      {data.flags.length > 0 && (
        <div className="space-y-1.5">
          <p className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
            Concerns Detected
          </p>
          <ul className="space-y-1">
            {data.flags.map((flag, i) => (
              <li key={i} className="flex items-start gap-1.5 text-xs text-muted-foreground">
                <AlertCircle className="h-3 w-3 shrink-0 mt-0.5 text-amber-500" />
                {flag}
              </li>
            ))}
          </ul>
        </div>
      )}

      {data.flags.length === 0 && (
        <div className="flex items-center gap-1.5 text-xs text-emerald-600 dark:text-emerald-400">
          <ShieldCheck className="h-3 w-3 shrink-0" />
          No suspicious patterns detected
        </div>
      )}
    </div>
  );
};

export default AuthenticityReport;

import { useState } from "react";
import { Bookmark, BookmarkCheck, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

interface AddToPoolButtonProps {
  resumeId: string;
  jobId: string;
  teamId: string;
  isInPool?: boolean;
  onPoolChange?: (inPool: boolean) => void;
  size?: "sm" | "default";
  variant?: "ghost" | "outline" | "default";
}

const AddToPoolButton = ({
  resumeId,
  jobId,
  teamId,
  isInPool = false,
  onPoolChange,
  size = "sm",
  variant = "outline",
}: AddToPoolButtonProps) => {
  const { user } = useAuth();
  const [inPool, setInPool] = useState(isInPool);
  const [loading, setLoading] = useState(false);

  const handleToggle = async () => {
    if (!user) {
      toast.error("You must be logged in");
      return;
    }

    setLoading(true);
    try {
      if (inPool) {
        // Remove from pool
        const { error } = await (supabase as any)
          .from("talent_pool")
          .delete()
          .eq("resume_id", resumeId)
          .eq("team_id", teamId);

        if (error) throw error;
        setInPool(false);
        onPoolChange?.(false);
        toast.success("Removed from talent pool");
      } else {
        // Add to pool
        const { error } = await (supabase as any)
          .from("talent_pool")
          .insert({
            resume_id: resumeId,
            job_id: jobId,
            team_id: teamId,
            added_by: user.id,
          });

        if (error) {
          if (error.code === "23505") {
            // Already in pool (unique constraint)
            setInPool(true);
            onPoolChange?.(true);
            toast.info("Already in talent pool");
            return;
          }
          throw error;
        }
        setInPool(true);
        onPoolChange?.(true);
        toast.success("Added to talent pool");
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to update talent pool";
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <TooltipProvider delayDuration={300}>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant={inPool ? "default" : variant}
            size={size}
            className={`h-8 gap-1.5 text-xs ${inPool ? "bg-primary/90" : ""}`}
            onClick={handleToggle}
            disabled={loading}
          >
            {loading ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : inPool ? (
              <BookmarkCheck className="h-3.5 w-3.5" />
            ) : (
              <Bookmark className="h-3.5 w-3.5" />
            )}
            {inPool ? "In Pool" : "Save to Pool"}
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          {inPool ? "Remove from talent pool" : "Save to talent pool for future roles"}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

export default AddToPoolButton;

