      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.access_token) throw new Error("Not authenticated");

      const res = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/ai-search`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${session.access_token}`,
            "apikey": import.meta.env.VITE_SUPABASE_ANON_KEY,
          },
          body: JSON.stringify({ query: trimmed, job_id: jobId }),
        }
      );

      const json = await res.json();
      if (!res.ok) throw new Error(json.error ?? "Search failed");

      setResults(json.results ?? []);
      setFilters(json.filters ?? null);
      setSearched(true);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Search failed";
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  }, [jobId]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") handleSearch(query);
  };

  const handleClear = () => {
    setQuery("");
    setResults([]);
    setFilters(null);
    setSearched(false);
    inputRef.current?.focus();
  };

  const handleExampleClick = (example: string) => {
    setQuery(example);
    handleSearch(example);
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className={cn("h-8 gap-1.5 text-xs", className)}
          onClick={() => {
            setOpen(true);
            setTimeout(() => inputRef.current?.focus(), 50);
          }}
        >
          <Sparkles className="h-3.5 w-3.5 text-primary" />
          AI Search
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="end"
        className="w-[480px] p-0 shadow-lg"
        onOpenAutoFocus={(e) => e.preventDefault()}
      >
        {/* Search bar */}
        <div className="flex items-center gap-2 p-3 border-b border-border">
          <Search className="h-4 w-4 text-muted-foreground shrink-0" />
          <Input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="e.g. React developers in New York with 80%+ score"
            className="h-8 border-0 bg-transparent p-0 text-sm focus-visible:ring-0 shadow-none"
          />
          {query && (
            <button onClick={handleClear} className="text-muted-foreground hover:text-foreground transition-colors">
              <X className="h-3.5 w-3.5" />
            </button>
          )}
          <Button size="sm" className="h-7 text-xs shrink-0 gap-1" onClick={() => handleSearch(query)} disabled={loading || !query.trim()}>
            {loading ? <Loader2 className="h-3 w-3 animate-spin" /> : <Sparkles className="h-3 w-3" />}
            Search
          </Button>
        </div>

        <div className="max-h-[400px] overflow-y-auto">
          {/* Parsed filters */}
          {filters && !loading && (
            <div className="px-3 py-2 border-b border-border bg-muted/30 flex flex-wrap gap-1">
              {filters.min_score != null && (
                <Badge variant="secondary" className="text-[10px] h-4 px-1.5">score ≥ {filters.min_score}%</Badge>
              )}
              {filters.skills?.map((s) => (
                <Badge key={s} variant="secondary" className="text-[10px] h-4 px-1.5">{s}</Badge>
              ))}
              {filters.location && (
                <Badge variant="secondary" className="text-[10px] h-4 px-1.5 gap-0.5">
                  <MapPin className="h-2.5 w-2.5" />{filters.location}
                </Badge>
              )}
              {filters.stages?.map((st) => (
                <Badge key={st} variant="secondary" className="text-[10px] h-4 px-1.5 capitalize">{st}</Badge>
              ))}
            </div>
          )}

          {/* Loading */}
          {loading && (
            <div className="flex items-center gap-2 px-3 py-6 justify-center">
              <Loader2 className="h-4 w-4 animate-spin text-primary" />
              <p className="text-sm text-muted-foreground">Parsing query and searching…</p>
            </div>
          )}

          {/* Example queries */}
          {!loading && !searched && (
            <div className="p-3 space-y-2">
              <p className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground px-0.5">
                Try these
              </p>
              <div className="space-y-1">
                {EXAMPLE_QUERIES.map((ex) => (
                  <button
                    key={ex}
                    onClick={() => handleExampleClick(ex)}
                    className="w-full text-left px-2 py-1.5 rounded-md text-xs text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
                  >
                    {ex}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Results */}
          {!loading && searched && results.length === 0 && (
            <div className="flex flex-col items-center justify-center py-8 space-y-2">
              <Search className="h-6 w-6 text-muted-foreground/40" />
              <p className="text-sm text-muted-foreground">No candidates matched your query</p>
              <p className="text-xs text-muted-foreground/70">Try adjusting your search terms</p>
            </div>
          )}

          {!loading && results.length > 0 && (
            <div className="divide-y divide-border/50">
              {results.map((r) => (
                <button
                  key={r.resume_id}
                  className="w-full text-left px-3 py-2.5 hover:bg-muted/50 transition-colors group"
                  onClick={() => {
                    onSelectCandidate?.(r.resume_id, r.job_id);
                    setOpen(false);
                  }}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <span className="text-sm font-medium truncate">
                          {r.candidate_name ?? r.filename}
                        </span>
                        {r.authenticity_json && (
                          <AuthenticityBadge data={r.authenticity_json} />
                        )}
                      </div>
                      <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                        {r.candidate_location && (
                          <span className="flex items-center gap-0.5 text-[11px] text-muted-foreground">
                            <MapPin className="h-2.5 w-2.5" />{r.candidate_location}
                          </span>
                        )}
                        {r.job_title && !jobId && (
                          <span className="text-[11px] text-muted-foreground">{r.job_title}</span>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                      <span className={cn("text-sm font-bold tabular-nums", getScoreColor(r.overall_score))}>
                        {r.overall_score.toFixed(0)}%
                      </span>
                      <ExternalLink className="h-3 w-3 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity" />
                    </div>
                  </div>
                </button>
              ))}
            </div>
          )}

          {results.length > 0 && (
            <div className="px-3 py-2 border-t border-border bg-muted/20">
              <p className="text-[11px] text-muted-foreground">{results.length} candidate{results.length !== 1 ? "s" : ""} found</p>
            </div>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
};

