type ActionType = "send_email" | "add_tag" | "assign_member" | "webhook";

interface Automation {
  id: string;
  team_id: string;
  stage_name: string;
  action_type: ActionType;
  action_config: Record<string, string>;
  is_active: boolean;
  created_at: string;
}

interface NewAutomation {
  stage_name: string;
  action_type: ActionType;
  action_config: Record<string, string>;
}

const STAGES = [
  "applied",
  "screened",
  "interview",
  "offer",
  "hired",
  "rejected",
];

const ACTION_ICONS: Record<ActionType, React.ElementType> = {
  send_email: Mail,
  add_tag: Tag,
  assign_member: UserCheck,
  webhook: Webhook,
};

const ACTION_LABELS: Record<ActionType, string> = {
  send_email: "Send Email",
  add_tag: "Add Tag",
  assign_member: "Assign Member",
  webhook: "Webhook",
};

function AutomationSkeleton() {
  return (
    <div className="space-y-2">
      {[1, 2].map((i) => (
        <div key={i} className="flex items-center gap-3 p-3 border border-border rounded-lg">
          <Skeleton className="h-4 w-4 rounded" />
          <div className="flex-1 space-y-1">
            <Skeleton className="h-4 w-48" />
            <Skeleton className="h-3 w-32" />
          </div>
          <Skeleton className="h-5 w-8 rounded-full" />
        </div>
      ))}
    </div>
  );
}

function ActionConfigFields({
  actionType,
  config,
  onChange,
}: {
  actionType: ActionType;
  config: Record<string, string>;
  onChange: (key: string, value: string) => void;
}) {
  switch (actionType) {
    case "send_email":
      return (
        <div className="space-y-3">
          <div className="space-y-1">
            <Label className="text-xs">Email Template Subject</Label>
            <Input
              value={config.subject ?? ""}
              onChange={(e) => onChange("subject", e.target.value)}
              placeholder="e.g. Interview invitation for {candidate_name}"
              className="h-8 text-xs"
            />
          </div>
          <div className="space-y-1">
            <Label className="text-xs">Email Body (short)</Label>
            <Input
              value={config.body ?? ""}
              onChange={(e) => onChange("body", e.target.value)}
              placeholder="e.g. Hi {candidate_name}, you've been moved to..."
              className="h-8 text-xs"
            />
          </div>
        </div>
      );
    case "add_tag":
      return (
        <div className="space-y-1">
          <Label className="text-xs">Tag Name</Label>
          <Input
            value={config.tag ?? ""}
            onChange={(e) => onChange("tag", e.target.value)}
            placeholder="e.g. shortlisted"
            className="h-8 text-xs"
          />
        </div>
      );
    case "assign_member":
      return (
        <div className="space-y-1">
          <Label className="text-xs">Member Email</Label>
          <Input
            value={config.member_email ?? ""}
            onChange={(e) => onChange("member_email", e.target.value)}
            placeholder="e.g. recruiter@company.com"
            className="h-8 text-xs"
          />
        </div>
      );
    case "webhook":
      return (
        <div className="space-y-1">
          <Label className="text-xs">Webhook URL</Label>
          <Input
            value={config.url ?? ""}
            onChange={(e) => onChange("url", e.target.value)}
            placeholder="https://hooks.example.com/..."
            className="h-8 text-xs"
          />
        </div>
      );
    default:
      return null;
  }
}

function getConfigSummary(actionType: ActionType, config: Record<string, string>): string {
  switch (actionType) {
    case "send_email": return config.subject ? `Subject: ${config.subject}` : "No subject set";
    case "add_tag": return config.tag ? `Tag: ${config.tag}` : "No tag set";
    case "assign_member": return config.member_email ? `To: ${config.member_email}` : "No member set";
    case "webhook": return config.url ? config.url : "No URL set";
    default: return "";
  }
}

interface StageAutomationManagerProps {
  teamId: string;
}

const StageAutomationManager = ({ teamId }: StageAutomationManagerProps) => {
  const qc = useQueryClient();
  const [dialogOpen, setDialogOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [togglingId, setTogglingId] = useState<string | null>(null);
  const [newAuto, setNewAuto] = useState<NewAutomation>({
    stage_name: "screened",
    action_type: "send_email",
    action_config: {},
  });

  const { data: automations = [], isLoading } = useQuery<Automation[]>({
    queryKey: ["stage_automations", teamId],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("stage_automations")
        .select("*")
        .eq("team_id", teamId)
        .order("created_at", { ascending: true });
      if (error) throw error;
      return data ?? [];
    },
    staleTime: 30_000,
  });

  const handleCreate = async () => {
    if (!newAuto.stage_name || !newAuto.action_type) return;
    setSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("stage_automations")
        .insert({
          team_id: teamId,
          stage_name: newAuto.stage_name,
          action_type: newAuto.action_type,
          action_config: newAuto.action_config,
          is_active: true,
        });
      if (error) throw error;
      toast.success("Automation created");
      qc.invalidateQueries({ queryKey: ["stage_automations", teamId] });
      setDialogOpen(false);
      setNewAuto({ stage_name: "screened", action_type: "send_email", action_config: {} });
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Failed to create automation");
    } finally {
      setSaving(false);
    }
  };

  const handleToggle = async (auto: Automation) => {
    setTogglingId(auto.id);
    try {
      const { error } = await (supabase as any)
        .from("stage_automations")
        .update({ is_active: !auto.is_active })
        .eq("id", auto.id);
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["stage_automations", teamId] });
      toast.success(auto.is_active ? "Automation disabled" : "Automation enabled");
    } catch {
      toast.error("Failed to update automation");
    } finally {
      setTogglingId(null);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const { error } = await (supabase as any)
        .from("stage_automations")
        .delete()
        .eq("id", id);
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["stage_automations", teamId] });
      toast.success("Automation deleted");
    } catch {
      toast.error("Failed to delete automation");
    }
  };

  return (
    <>
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-semibold flex items-center gap-2">
              <Zap className="h-4 w-4 text-primary" />
              Stage Automations
              {!isLoading && automations.length > 0 && (
                <Badge variant="secondary" className="text-xs">{automations.length}</Badge>
              )}
            </CardTitle>
            <Button
              size="sm"
              variant="outline"
              className="h-7 text-xs gap-1"
              onClick={() => setDialogOpen(true)}
            >
              <Plus className="h-3 w-3" />
              Add
            </Button>
          </div>
        </CardHeader>
        <CardContent className="pb-4">
          {isLoading ? (
            <AutomationSkeleton />
          ) : automations.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 space-y-2 text-center">
              <div className="rounded-xl bg-muted/50 p-3">
                <Zap className="h-6 w-6 text-muted-foreground/40" />
              </div>
              <p className="text-sm font-medium text-muted-foreground">No automations yet</p>
              <p className="text-xs text-muted-foreground/70 max-w-xs">
                Trigger actions automatically when candidates move through pipeline stages.
              </p>
              <Button size="sm" variant="outline" className="mt-1 gap-1 text-xs" onClick={() => setDialogOpen(true)}>
                <Plus className="h-3 w-3" /> Create first automation
              </Button>
            </div>
          ) : (
            <div className="space-y-2">
              {automations.map((auto) => {
                const Icon = ACTION_ICONS[auto.action_type];
                return (
                  <div
                    key={auto.id}
                    className={`flex items-center gap-3 p-3 rounded-lg border transition-colors ${
                      auto.is_active
                        ? "border-border bg-background"
                        : "border-border/50 bg-muted/20 opacity-60"
                    }`}
                  >
                    <Icon className="h-4 w-4 text-primary shrink-0" />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <span className="text-xs font-medium capitalize">{auto.stage_name}</span>
                        <span className="text-[10px] text-muted-foreground">→</span>
                        <span className="text-xs text-muted-foreground">{ACTION_LABELS[auto.action_type]}</span>
                      </div>
                      <p className="text-[11px] text-muted-foreground/70 truncate mt-0.5">
                        {getConfigSummary(auto.action_type, auto.action_config)}
                      </p>
                    </div>
                    <div className="flex items-center gap-1.5 shrink-0">
                      <Switch
                        checked={auto.is_active}
                        onCheckedChange={() => handleToggle(auto)}
                        disabled={togglingId === auto.id}
                        className="scale-75"
                      />
                      <AlertDialog>
                        <AlertDialogTrigger asChild>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-6 w-6 text-muted-foreground hover:text-destructive"
                          >
                            <Trash2 className="h-3 w-3" />
                          </Button>
                        </AlertDialogTrigger>
                        <AlertDialogContent>
                          <AlertDialogHeader>
                            <AlertDialogTitle>Delete automation?</AlertDialogTitle>
                            <AlertDialogDescription>
                              This automation will stop triggering for new stage changes. This cannot be undone.
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel>Cancel</AlertDialogCancel>
                            <AlertDialogAction
                              onClick={() => handleDelete(auto.id)}
                              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                            >
                              Delete
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Zap className="h-4 w-4 text-primary" />
              New Stage Automation
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div className="space-y-1.5">
              <Label className="text-xs">When candidate moves to</Label>
              <Select
                value={newAuto.stage_name}
                onValueChange={(v) => setNewAuto((prev) => ({ ...prev, stage_name: v }))}
              >
                <SelectTrigger className="h-8 text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {STAGES.map((s) => (
                    <SelectItem key={s} value={s} className="capitalize text-xs">{s}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs">Trigger action</Label>
              <Select
                value={newAuto.action_type}
                onValueChange={(v) =>
                  setNewAuto((prev) => ({
                    ...prev,
                    action_type: v as ActionType,
                    action_config: {},
                  }))
                }
              >
                <SelectTrigger className="h-8 text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {(Object.keys(ACTION_LABELS) as ActionType[]).map((at) => (
                    <SelectItem key={at} value={at} className="text-xs">{ACTION_LABELS[at]}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="pt-1">
              <ActionConfigFields
                actionType={newAuto.action_type}
                config={newAuto.action_config}
                onChange={(key, value) =>
                  setNewAuto((prev) => ({
                    ...prev,
                    action_config: { ...prev.action_config, [key]: value },
                  }))
                }
              />
            </div>

            <div className="flex items-start gap-2 rounded-md border border-amber-200 bg-amber-50 dark:border-amber-800 dark:bg-amber-900/20 p-2.5">
              <AlertCircle className="h-3.5 w-3.5 text-amber-600 shrink-0 mt-0.5" />
              <p className="text-[11px] text-amber-700 dark:text-amber-400">
                Automations run when stage changes are made manually. Actual email delivery requires your email integration to be configured.
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" size="sm" onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button size="sm" onClick={handleCreate} disabled={saving} className="gap-1.5">
              {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Zap className="h-3.5 w-3.5" />}
              Create Automation
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
};

export default StageAutomationManager;

