    experience_score: number;
    authenticity_json: {
      authenticity_score: number;
      risk_level: "low" | "medium" | "high";
      flags: string[];
      summary: string;
    } | null;
  } | null;
}

const getScoreColor = (score: number) => {
  if (score >= 70) return "text-emerald-600 dark:text-emerald-400";
  if (score >= 40) return "text-amber-600 dark:text-amber-400";
  return "text-red-600 dark:text-red-400";
};

function PoolSkeleton() {
  return (
    <div className="space-y-0.5">
      {[1, 2, 3, 4, 5].map((i) => (
        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border">
          <Skeleton className="h-4 w-40" />
          <Skeleton className="h-4 w-28" />
          <Skeleton className="h-4 w-20" />
          <Skeleton className="h-4 w-16 ml-auto" />
        </div>
      ))}
    </div>
  );
}

const TalentPool = () => {
  const navigate = useNavigate();
  const { team } = useTeam();
  const qc = useQueryClient();

  const [search, setSearch] = useState("");
  const [removingId, setRemovingId] = useState<string | null>(null);
  const [notesEntry, setNotesEntry] = useState<PoolEntry | null>(null);
  const [notesText, setNotesText] = useState("");
  const [savingNotes, setSavingNotes] = useState(false);

  const { data: poolEntries = [], isLoading, error, refetch } = useQuery<PoolEntry[]>({
    queryKey: ["talent_pool", team?.id],
    queryFn: async () => {
      if (!team?.id) return [];
      const { data, error } = await (supabase as any)
        .from("talent_pool")
        .select(`
          id,
          resume_id,
          original_job_id,
          added_by,
          notes,
          created_at,
          resume:resumes (
            id,
            filename,
            candidate_name,
            candidate_email,
            candidate_location,
            job_id
          ),
          original_job:jobs!talent_pool_original_job_id_fkey (
            id,
            title
          )
        `)
        .eq("team_id", team.id)
        .order("created_at", { ascending: false });

      if (error) throw error;

      // Fetch results separately
      const resumeIds = (data ?? []).map((e: any) => e.resume_id);
      if (resumeIds.length === 0) return [];

      const { data: results } = await (supabase as any)
        .from("results")
        .select("resume_id, overall_score, skill_score, experience_score, authenticity_json")
        .in("resume_id", resumeIds);

      const resultsByResumeId: Record<string, any> = {};
      (results ?? []).forEach((r: any) => {
        resultsByResumeId[r.resume_id] = r;
      });

      return (data ?? []).map((e: any) => ({
        ...e,
        result: resultsByResumeId[e.resume_id] ?? null,
      }));
    },
    enabled: !!team?.id,
    staleTime: 30_000,
  });

  const handleRemove = async (entryId: string) => {
    setRemovingId(entryId);
    try {
      const { error } = await (supabase as any)
        .from("talent_pool")
        .delete()
        .eq("id", entryId);
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["talent_pool", team?.id] });
      toast.success("Removed from talent pool");
    } catch {
      toast.error("Failed to remove from pool");
    } finally {
      setRemovingId(null);
    }
  };

  const openNotes = (entry: PoolEntry) => {
    setNotesEntry(entry);
    setNotesText(entry.notes ?? "");
  };

  const handleSaveNotes = async () => {
    if (!notesEntry) return;
    setSavingNotes(true);
    try {
      const { error } = await (supabase as any)
        .from("talent_pool")
        .update({ notes: notesText.trim() || null })
        .eq("id", notesEntry.id);
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["talent_pool", team?.id] });
      toast.success("Notes saved");
      setNotesEntry(null);
    } catch {
      toast.error("Failed to save notes");
    } finally {
      setSavingNotes(false);
    }
  };

  const filtered = poolEntries.filter((entry) => {
    if (!search) return true;
    const q = search.toLowerCase();
    const name = (entry.resume?.candidate_name ?? entry.resume?.filename ?? "").toLowerCase();
    const location = (entry.resume?.candidate_location ?? "").toLowerCase();
    const jobTitle = (entry.original_job?.title ?? "").toLowerCase();
    return name.includes(q) || location.includes(q) || jobTitle.includes(q);
  });

  if (!team) {
    return (
      <SidebarLayout>
        <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          <div className="flex flex-col items-center justify-center py-16 space-y-3 text-center">
            <div className="rounded-xl bg-muted/50 p-4">
              <Bookmark className="h-8 w-8 text-muted-foreground/40" />
            </div>
            <h2 className="text-base font-semibold">No Team Found</h2>
            <p className="text-sm text-muted-foreground max-w-sm">
              Create or join a team to use the talent pool feature.
            </p>
            <Button size="sm" onClick={() => navigate("/team")}>
              Go to Team
            </Button>
          </div>
        </main>
      </SidebarLayout>
    );
  }

  return (
    <SidebarLayout>
      <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="flex items-center justify-between mb-1">
          <h1 className="text-2xl font-bold text-foreground">Talent Pool</h1>
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8"
            onClick={() => refetch()}
            disabled={isLoading}
            aria-label="Refresh"
          >
            <RefreshCw className={`h-4 w-4 ${isLoading ? "animate-spin" : ""}`} />
          </Button>
        </div>
        <p className="text-sm text-muted-foreground mb-6">
          Candidates saved for future roles across your team.
        </p>

        {/* Search */}
        <div className="relative mb-4">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by name, location, or job title…"
            className="pl-9 h-9"
          />
        </div>

        {/* Error */}
        {!isLoading && error && (
          <Card className="border-destructive/50 mb-6">
            <CardContent className="py-6 text-center">
              <AlertCircle className="h-7 w-7 text-destructive mx-auto mb-2" />
              <p className="text-sm text-muted-foreground">Failed to load talent pool. Please try again.</p>
              <Button size="sm" variant="outline" className="mt-3 gap-1.5" onClick={() => refetch()}>
                <RefreshCw className="h-3.5 w-3.5" /> Retry
              </Button>
            </CardContent>
          </Card>
        )}

        {/* Table */}
        <Card className="border border-border/60 shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-semibold flex items-center gap-2">
              <Bookmark className="h-4 w-4 text-primary" />
              Pooled Candidates
              {!isLoading && (
                <Badge variant="secondary" className="text-xs ml-1">{filtered.length}</Badge>
              )}
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            {isLoading ? (
              <PoolSkeleton />
            ) : filtered.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-14 space-y-3 text-center px-4">
                <div className="rounded-xl bg-muted/50 p-4">
                  <Bookmark className="h-7 w-7 text-muted-foreground/40" />
                </div>
                <div className="space-y-1">
                  <p className="text-sm font-medium">
                    {search ? "No candidates match your search" : "Talent pool is empty"}
                  </p>
                  <p className="text-sm text-muted-foreground max-w-xs">
                    {search
                      ? "Try different keywords."
                      : "Save strong candidates from job rankings to build your talent pool."}
                  </p>
                </div>
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="text-xs">Candidate</TableHead>
                    <TableHead className="text-xs">Original Job</TableHead>
                    <TableHead className="text-xs">Score</TableHead>
                    <TableHead className="text-xs">Authenticity</TableHead>
                    <TableHead className="text-xs">Added</TableHead>
                    <TableHead className="text-xs w-20" />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filtered.map((entry) => {
                    const name = entry.resume?.candidate_name ?? entry.resume?.filename ?? "Unknown";
                    const score = entry.result?.overall_score ?? null;
                    return (
                      <TableRow key={entry.id}>
                        <TableCell>
                          <div className="flex flex-col gap-0.5">
                            <span className="text-sm font-medium">{name}</span>
                            <div className="flex items-center gap-2 text-xs text-muted-foreground">
                              {entry.resume?.candidate_location && (
                                <span className="flex items-center gap-0.5">
                                  <MapPin className="h-2.5 w-2.5" />
                                  {entry.resume.candidate_location}
                                </span>
                              )}
                              {entry.resume?.candidate_email && (
                                <span>{entry.resume.candidate_email}</span>
                              )}
                            </div>
                            {entry.notes && (
                              <p className="text-[11px] text-muted-foreground italic truncate max-w-[200px]">
                                "{entry.notes}"
                              </p>
                            )}
                          </div>
                        </TableCell>
                        <TableCell>
                          {entry.original_job?.title ? (
                            <div className="flex items-center gap-1 text-xs text-muted-foreground">
                              <Briefcase className="h-3 w-3 shrink-0" />
                              {entry.original_job.title}
                            </div>
                          ) : (
                            <span className="text-xs text-muted-foreground/50">—</span>
                          )}
                        </TableCell>
                        <TableCell>
                          {score != null ? (
                            <span className={`text-sm font-semibold tabular-nums ${getScoreColor(score)}`}>
                              {score.toFixed(0)}%
                            </span>
                          ) : (
                            <span className="text-xs text-muted-foreground/50">—</span>
                          )}
                        </TableCell>
                        <TableCell>
                          <AuthenticityBadge data={entry.result?.authenticity_json} showScore />
                        </TableCell>
                        <TableCell className="text-xs text-muted-foreground">
                          {format(new Date(entry.created_at), "MMM d, yyyy")}
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1">
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-7 w-7 text-muted-foreground hover:text-primary"
                              onClick={() => openNotes(entry)}
                              aria-label="Edit notes"
                            >
                              <StickyNote className="h-3.5 w-3.5" />
                            </Button>
                            <AlertDialog>
                              <AlertDialogTrigger asChild>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="h-7 w-7 text-muted-foreground hover:text-destructive"
                                  disabled={removingId === entry.id}
                                >
                                  {removingId === entry.id ? (
                                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                                  ) : (
                                    <Trash2 className="h-3.5 w-3.5" />
                                  )}
                                </Button>
                              </AlertDialogTrigger>
                              <AlertDialogContent>
                                <AlertDialogHeader>
                                  <AlertDialogTitle>Remove from pool?</AlertDialogTitle>
                                  <AlertDialogDescription>
                                    {name} will be removed from the talent pool. This cannot be undone.
                                  </AlertDialogDescription>
                                </AlertDialogHeader>
                                <AlertDialogFooter>
                                  <AlertDialogCancel>Cancel</AlertDialogCancel>
                                  <AlertDialogAction
                                    onClick={() => handleRemove(entry.id)}
                                    className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                                  >
                                    Remove
                                  </AlertDialogAction>
                                </AlertDialogFooter>
                              </AlertDialogContent>
                            </AlertDialog>
                          </div>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </main>

      {/* Notes Dialog */}
      <Dialog open={!!notesEntry} onOpenChange={(o) => { if (!o) setNotesEntry(null); }}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-sm">
              <StickyNote className="h-4 w-4 text-primary" />
              Notes for {notesEntry?.resume?.candidate_name ?? notesEntry?.resume?.filename}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-1.5 py-1">
            <Label className="text-xs">Internal notes (visible to team)</Label>
            <Textarea
              value={notesText}
              onChange={(e) => setNotesText(e.target.value)}
              placeholder="Add context, follow-up reminders, etc."
              rows={4}
              className="text-sm resize-none"
            />
          </div>
          <DialogFooter>
            <Button variant="outline" size="sm" onClick={() => setNotesEntry(null)}>Cancel</Button>
            <Button size="sm" onClick={handleSaveNotes} disabled={savingNotes} className="gap-1.5">
              {savingNotes ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : null}
              Save Notes
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </SidebarLayout>
  );
};

export default TalentPool;

